const std = @import("std");
const math = std.math;
const mem = std.mem;
const testing = std.testing;
const Allocator = mem.Allocator;
const ArrayList = std.ArrayList;
const HashMap = std.HashMap;
const Random = std.rand.Random;
const DefaultPrng = std.rand.DefaultPrng;
const meta = @import("meta.zig");
const c = @cImport({
    @cInclude("math.h");
    @cInclude("complex.h");
    @cInclude("immintrin.h");
    @cInclude("fftw3.h");
});

pub const DType = enum { f64, f32, i64, i32, c64 };

pub const Shape = []const usize;

pub const Tensor = struct {
    allocator: Allocator,
    data: []f64,
    shape: Shape,
    strides: []usize,
    dtype: DType = .f64,
    offset: usize = 0,
    is_view: bool = false,

    pub fn init(allocator: Allocator, shape: Shape, dtype: DType) !Tensor {
        const total = totalElements(shape);
        const data = try allocator.alloc(f64, total);
        @memset(data, 0.0);
        const shape_copy = try allocator.dupe(usize, shape);
        var strides = try allocator.alloc(usize, shape.len);
        if (shape.len > 0) {
            strides[shape.len - 1] = 1;
            var i: usize = shape.len;
            while (i > 1) {
                i -= 1;
                strides[i - 1] = strides[i] * shape[i];
            }
        }
        return Tensor{
            .allocator = allocator,
            .data = data,
            .shape = shape_copy,
            .strides = strides,
            .dtype = dtype,
        };
    }

    pub fn deinit(self: *Tensor) void {
        if (!self.is_view) {
            self.allocator.free(self.data);
        }
        self.allocator.free(self.shape);
        self.allocator.free(self.strides);
    }

    pub fn view(self: Tensor, new_shape: Shape) !Tensor {
        if (self.data.len != totalElements(new_shape)) return error.ShapeMismatch;
        const shape_copy = try self.allocator.dupe(usize, new_shape);
        var strides = try self.allocator.alloc(usize, new_shape.len);
        if (new_shape.len > 0) {
            strides[new_shape.len - 1] = 1;
            var i: usize = new_shape.len;
            while (i > 1) {
                i -= 1;
                strides[i - 1] = strides[i] * new_shape[i];
            }
        }
        return Tensor{
            .allocator = self.allocator,
            .data = self.data,
            .shape = shape_copy,
            .strides = strides,
            .dtype = self.dtype,
            .offset = self.offset,
            .is_view = true,
        };
    }

    pub fn totalElements(shape: Shape) usize {
        var total: usize = 1;
        for (shape) |dim| total *= dim;
        return total;
    }

    pub fn matmul(self: Tensor, other: Tensor, result: *Tensor) !void {
        if (self.shape.len < 2 or other.shape.len < 2 or self.shape[self.shape.len - 1] != other.shape[other.shape.len - 2]) {
            return error.ShapeMismatch;
        }
        const m = self.shape[self.shape.len - 2];
        const n = other.shape[other.shape.len - 1];
        const k = self.shape[self.shape.len - 1];
        if (result.shape.len != 2 or result.shape[0] != m or result.shape[1] != n) {
            return error.ResultShapeMismatch;
        }
        @memset(result.data, 0.0);
        const self_ptr = @ptrCast([*]const f64, self.data.ptr + self.offset);
        const other_ptr = @ptrCast([*]const f64, other.data.ptr + other.offset);
        const res_ptr = @as([*]f64, @ptrCast(result.data.ptr));
        if (@import("builtin").target.cpu.features.contains(.avx2)) {
            self.avx_matmul(self_ptr, other_ptr, res_ptr, m, k, n);
        } else {
            self.serial_matmul(self_ptr, other_ptr, res_ptr, m, k, n);
        }
    }

    fn serial_matmul(self: *const Tensor, a: [*]const f64, b: [*]const f64, c: [*]f64, m: usize, k: usize, n: usize) void {
        var i: usize = 0;
        while (i < m) : (i += 1) {
            var j: usize = 0;
            while (j < n) : (j += 1) {
                var sum: f64 = 0.0;
                var l: usize = 0;
                while (l < k) : (l += 1) {
                    sum += a[i * k + l] * b[l * n + j];
                }
                c[i * n + j] += sum;
            }
        }
    }

    fn avx_matmul(self: *const Tensor, a: [*]const f64, b: [*]const f64, c: [*]f64, m: usize, k: usize, n: usize) void {
        var i: usize = 0;
        while (i < m) : (i += 1) {
            var j: usize = 0;
            while (j + 3 < n) : (j += 4) {
                var sum: @Vector(4, f64) = @splat(0.0);
                var l: usize = 0;
                while (l < k) : (l += 1) {
                    const a_val = a[i * k + l];
                    const a_splat: @Vector(4, f64) = @splat(a_val);
                    const b_ptr = b + l * n + j;
                    const b_array = b_ptr[0..4].*;
                    const b_vec: @Vector(4, f64) = @as(@Vector(4, f64), b_array);
                    sum += a_splat * b_vec;
                }
                const c_ptr = c + i * n + j;
                const old_c = c_ptr[0..4].*;
                const old_c_vec: @Vector(4, f64) = @as(@Vector(4, f64), old_c);
                const new_c: @Vector(4, f64) = old_c_vec + sum;
                c_ptr[0..4].* = @as([4]f64, new_c);
            }
            while (j < n) : (j += 1) {
                var sum: f64 = 0.0;
                var l: usize = 0;
                while (l < k) : (l += 1) {
                    sum += a[i * k + l] * b[l * n + j];
                }
                c[i * n + j] += sum;
            }
        }
    }

    pub fn layernorm(self: *Tensor, gamma: []f64, beta: []f64, eps: f64) !void {
        if (self.shape.len == 0) return error.InvalidShape;
        const last_dim = self.shape[self.shape.len - 1];
        if (gamma.len < last_dim or beta.len < last_dim) return error.GammaBetaMismatch;
        const means = try self.computeMeansAlongLastDim();
        defer self.allocator.free(means);
        const variances = try self.computeVariancesAlongLastDim(means, eps);
        defer self.allocator.free(variances);
        var idx: usize = 0;
        while (idx < self.totalElements(self.shape)) : (idx += 1) {
            const pos = idx % last_dim;
            const row = idx / last_dim;
            const inv_sqrt_var = 1.0 / @sqrt(variances[row]);
            const val = self.get(idx);
            const new_val = (val - means[row]) * inv_sqrt_var * gamma[pos] + beta[pos];
            self.set(idx, new_val);
        }
    }

    fn computeMeansAlongLastDim(self: *const Tensor) ![]f64 {
        if (self.shape.len == 0) return try self.allocator.alloc(f64, 0);
        const last_dim = self.shape[self.shape.len - 1];
        const num_vectors = self.totalElements(self.shape) / last_dim;
        var means = try self.allocator.alloc(f64, num_vectors);
        var vec_idx: usize = 0;
        var i: usize = 0;
        while (i < self.totalElements(self.shape)) : (i += last_dim) {
            var sum: f64 = 0.0;
            var j: usize = 0;
            while (j < last_dim) : (j += 1) {
                sum += self.get(i + j);
            }
            means[vec_idx] = sum / @as(f64, @floatFromInt(last_dim));
            vec_idx += 1;
        }
        return means;
    }

    fn computeVariancesAlongLastDim(self: *const Tensor, means: []f64, eps: f64) ![]f64 {
        if (self.shape.len == 0) return try self.allocator.alloc(f64, 0);
        const last_dim = self.shape[self.shape.len - 1];
        const num_vectors = self.totalElements(self.shape) / last_dim;
        var variances = try self.allocator.alloc(f64, num_vectors);
        var vec_idx: usize = 0;
        var i: usize = 0;
        while (i < self.totalElements(self.shape)) : (i += last_dim) {
            var var_sum: f64 = 0.0;
            var j: usize = 0;
            while (j < last_dim) : (j += 1) {
                const diff = self.get(i + j) - means[vec_idx];
                var_sum += diff * diff;
            }
            variances[vec_idx] = var_sum / @as(f64, @floatFromInt(last_dim - 1)) + eps;
            vec_idx += 1;
        }
        return variances;
    }

    pub fn softmax(self: *Tensor) !void {
        if (self.shape.len == 0) return;
        const last_dim = self.shape[self.shape.len - 1];
        const num_vectors = self.totalElements(self.shape) / last_dim;
        var vec_idx: usize = 0;
        while (vec_idx < num_vectors) : (vec_idx += 1) {
            const base_flat = vec_idx * last_dim;
            var max_val: f64 = std.math.floatMin(f64);
            var j: usize = 0;
            while (j < last_dim) : (j += 1) {
                const val = self.get(base_flat + j);
                if (val > max_val) max_val = val;
            }
            var sum_exp: f64 = 0.0;
            j = 0;
            while (j < last_dim) : (j += 1) {
                sum_exp += math.exp(self.get(base_flat + j) - max_val);
            }
            const inv_sum = 1.0 / sum_exp;
            j = 0;
            while (j < last_dim) : (j += 1) {
                const new_val = math.exp(self.get(base_flat + j) - max_val) * inv_sum;
                self.set(base_flat + j, new_val);
            }
        }
    }

    pub fn spectralNorm(self: *const Tensor) f64 {
        if (self.shape.len < 2) return 0.0;
        const rows = self.shape[0];
        const cols = self.shape[1];
        var prng = std.rand.DefaultPrng.init(blk: {
            var seed: u64 = undefined;
            std.crypto.random.bytes(std.mem.asBytes(&seed));
            break :blk seed;
        });
        const rand = prng.random();
        var v = try self.allocator.alloc(f64, cols);
        defer self.allocator.free(v);
        for (v) |*val| val.* = rand.float(f64) * 2.0 - 1.0;
        var b = try self.allocator.alloc(f64, rows);
        defer self.allocator.free(b);
        self.powerIteration(v, b, 20);
        var norm_v: f64 = 0.0;
        for (v) |val| norm_v += val * val;
        return @sqrt(norm_v);
    }

    fn powerIteration(self: *const Tensor, v: []f64, b: []f64, iterations: usize) void {
        const rows = self.shape[0];
        const cols = self.shape[1];
        var i: usize = 0;
        while (i < iterations) : (i += 1) {
            @memset(b, 0.0);
            var j: usize = 0;
            while (j < cols) : (j += 1) {
                var k: usize = 0;
                while (k < rows) : (k += 1) {
                    b[k] += self.data[self.offset + k * cols + j] * v[j];
                }
            }
            var norm_b: f64 = 0.0;
            var k: usize = 0;
            while (k < rows) : (k += 1) {
                norm_b += b[k] * b[k];
            }
            norm_b = 1.0 / @sqrt(norm_b);
            k = 0;
            while (k < rows) : (k += 1) {
                b[k] *= norm_b;
            }
            @memset(v, 0.0);
            j = 0;
            while (j < rows) : (j += 1) {
                k = 0;
                while (k < cols) : (k += 1) {
                    v[k] += self.data[self.offset + j * cols + k] * b[j];
                }
            }
            norm_b = 0.0;
            k = 0;
            while (k < cols) : (k += 1) {
                norm_b += v[k] * v[k];
            }
            norm_b = 1.0 / @sqrt(norm_b);
            k = 0;
            while (k < cols) : (k += 1) {
                v[k] *= norm_b;
            }
        }
    }

    pub fn fft(self: *Tensor, direction: enum { forward, inverse }) !void {
        if (self.dtype != .c64) return error.MustBeComplex;
        if (self.shape.len != 1) return error.FFT1DOnly;
        const n = self.shape[0];
        if (n == 0) return;
        var plan: c.fftw_plan = undefined;
        const sign = if (direction == .forward) c.FFTW_FORWARD else c.FFTW_BACKWARD;
        const in_ptr = @as([*c]c.fftw_complex, @ptrCast(@alignCast(self.data.ptr + self.offset)));
        plan = c.fftw_plan_dft_1d(@as(c_int, @intCast(n)), in_ptr, in_ptr, sign, c.FFTW_ESTIMATE);
        c.fftw_execute(plan);
        c.fftw_destroy_plan(plan);
        if (direction == .inverse) {
            const div = @as(f64, @floatFromInt(n));
            var i: usize = 0;
            while (i < n) : (i += 1) {
                self.data[self.offset + 2 * i] /= div;
                self.data[self.offset + 2 * i + 1] /= div;
            }
        }
    }

    pub fn add(self: Tensor, other: Tensor) !Tensor {
        if (!std.mem.eql(usize, self.shape, other.shape)) return error.ShapeMismatch;
        var result = try Tensor.init(self.allocator, self.shape, self.dtype);
        var i: usize = 0;
        while (i < result.data.len) : (i += 1) {
            result.set(i, self.get(i) + other.get(i));
        }
        return result;
    }

    pub fn mul(self: Tensor, scalar: f64) !Tensor {
        var result = try Tensor.init(self.allocator, self.shape, self.dtype);
        var i: usize = 0;
        while (i < result.data.len) : (i += 1) {
            result.set(i, self.get(i) * scalar);
        }
        return result;
    }

    pub fn slice(self: Tensor, start: usize, end: usize, dim: usize) !Tensor {
        if (dim >= self.shape.len) return error.InvalidDim;
        if (start >= end or end > self.shape[dim]) return error.InvalidSlice;
        const shape_copy = try self.allocator.dupe(usize, self.shape);
        shape_copy[dim] = end - start;
        const strides_copy = try self.allocator.dupe(usize, self.strides);
        return Tensor{
            .allocator = self.allocator,
            .data = self.data,
            .shape = shape_copy,
            .strides = strides_copy,
            .dtype = self.dtype,
            .offset = self.offset + start * self.strides[dim],
            .is_view = true,
        };
    }

    pub fn broadcastTo(self: *Tensor, target_shape: Shape) !Tensor {
        const current_shape = self.shape;
        const current_strides = self.strides;
        var new_strides = try self.allocator.alloc(usize, target_shape.len);
        var broadcasted = false;
        var target_idx: usize = target_shape.len;
        var current_idx: usize = current_shape.len;
        var new_idx: usize = target_shape.len;
        while (new_idx > 0) {
            new_idx -= 1;
            target_idx -= 1;
            var t_dim = target_shape[target_idx];
            if (current_idx > 0) {
