            .allocator = self.allocator,
            .data = self.data,
            .shape = shape_copy,
            .strides = strides,
            .dtype = self.dtype,
            .offset = self.offset,
            .is_view = true,
        };
    }

    pub fn totalElements(shape: Shape) usize {
        if (shape.len == 0) return 1;
        var total: usize = 1;
        for (shape) |dim| total *= dim;
        return total;
