        while (vec_idx < num_vectors) : (vec_idx += 1) {
            const base_flat = vec_idx * last_dim;
            var max_val: f64 = -std.math.inf(f64);
            var j: usize = 0;
            while (j < last_dim) : (j += 1) {
                const val = self.get(base_flat + j);
                if (val > max_val) max_val = val;
            }
            var sum_exp: f64 = 0.0;
            j = 0;
            while (j < last_dim) : (j += 1) {
                sum_exp += math.exp(self.get(base_flat + j) - max_val);
            }
            const inv_sum = 1.0 / sum_exp;
            j = 0;
            while (j < last_dim) : (j += 1) {
                const new_val = math.exp(self.get(base_flat + j) - max_val) * inv_sum;
                self.set(base_flat + j, new_val);
            }
        }
    }

    pub fn spectralNorm(self: *const Tensor) !f64 {
        if (self.dtype != .f64) return error.InvalidDType;
        if (self.shape.len < 2) return 0.0;
        const rows = self.shape[0];
        const cols = self.shape[1];
        var seed: u64 = undefined;
        std.crypto.random.bytes(std.mem.asBytes(&seed));
        var prng = std.rand.DefaultPrng.init(seed);
        const rand = prng.random();
        var v = try self.allocator.alloc(f64, cols);
        defer self.allocator.free(v);
        var i: usize = 0;
        while (i < cols) : (i += 1) v[i] = rand.float(f64) * 2.0 - 1.0;
        var b = try self.allocator.alloc(f64, rows);
        defer self.allocator.free(b);
        self.powerIteration(v, b, 20);
        var norm_v: f64 = 0.0;
        for (v) |val| norm_v += val * val;
        return @sqrt(norm_v);
    }

    fn powerIteration(self: *const Tensor, v: []f64, b: []f64, iterations: usize) void {
        const rows = self.shape[0];
        const cols = self.shape[1];
        var it: usize = 0;
        while (it < iterations) : (it += 1) {
            @memset(b, 0.0);
            var j: usize = 0;
            while (j < cols) : (j += 1) {
                var k: usize = 0;
                while (k < rows) : (k += 1) {
                    b[k] += self.data[self.offset + k * cols + j] * v[j];
                }
            }
            var norm_b: f64 = 0.0;
            var k: usize = 0;
            while (k < rows) : (k += 1) {
                norm_b += b[k] * b[k];
            }
            norm_b = 1.0 / @sqrt(norm_b);
            k = 0;
            while (k < rows) : (k += 1) {
                b[k] *= norm_b;
            }
            @memset(v, 0.0);
            j = 0;
            while (j < rows) : (j += 1) {
                k = 0;
                while (k < cols) : (k += 1) {
                    v[k] += self.data[self.offset + j * cols + k] * b[j];
                }
            }
            var norm_v: f64 = 0.0;
            k = 0;
            while (k < cols) : (k += 1) {
                norm_v += v[k] * v[k];
            }
            norm_v = 1.0 / @sqrt(norm_v);
            k = 0;
            while (k < cols) : (k += 1) {
                v[k] *= norm_v;
            }
        }
    }

    pub fn fft(self: *Tensor, direction: enum { forward, inverse }) !void {
        if (self.dtype != .c64) return error.MustBeComplex;
        if (self.shape.len != 1) return error.FFT1DOnly;
        const n = self.shape[0];
        if (n == 0) return;
        if (!isPowerOfTwo(n)) return error.NonPowerOfTwo;
        const bits: u32 = @intCast(std.math.log2_int(u64, n));
        var i: usize = 0;
        while (i < n) : (i += 1) {
            const j = bitReverse(i, bits);
            if (j > i) {
                const ai = self.offset + i * 2;
                const aj = self.offset + j * 2;
                const r0 = self.data[ai];
                const i0 = self.data[ai + 1];
                self.data[ai] = self.data[aj];
                self.data[ai + 1] = self.data[aj + 1];
                self.data[aj] = r0;
                self.data[aj + 1] = i0;
            }
        }
        var len: usize = 2;
        while (len <= n) : (len <<= 1) {
            const half = len >> 1;
            const ang = (if (direction == .forward) -2.0 else 2.0) * std.math.pi / @as(f64, @floatFromInt(len));
            const wlen_cos = std.math.cos(ang);
            const wlen_sin = std.math.sin(ang);
            var start: usize = 0;
            while (start < n) : (start += len) {
                var w_cos: f64 = 1.0;
                var w_sin: f64 = 0.0;
                var j2: usize = 0;
                while (j2 < half) : (j2 += 1) {
                    const i0 = self.offset + (start + j2) * 2;
                    const i1 = self.offset + (start + j2 + half) * 2;
                    const ur = self.data[i0];
                    const ui = self.data[i0 + 1];
                    const vr = self.data[i1];
                    const vi = self.data[i1 + 1];
                    const tr = vr * w_cos - vi * w_sin;
                    const ti = vr * w_sin + vi * w_cos;
                    self.data[i0] = ur + tr;
                    self.data[i0 + 1] = ui + ti;
                    self.data[i1] = ur - tr;
                    self.data[i1 + 1] = ui - ti;
                    const nw_cos = w_cos * wlen_cos - w_sin * wlen_sin;
                    const nw_sin = w_cos * wlen_sin + w_sin * wlen_cos;
                    w_cos = nw_cos;
                    w_sin = nw_sin;
                }
            }
        }
        if (direction == .inverse) {
            const inv_n = 1.0 / @as(f64, @floatFromInt(n));
            var k: usize = 0;
            while (k < n) : (k += 1) {
                const idx = self.offset + k * 2;
                self.data[idx] *= inv_n;
                self.data[idx + 1] *= inv_n;
            }
        }
    }

    pub fn add(self: Tensor, other: Tensor) !Tensor {
        if (self.dtype != other.dtype) return error.InvalidDType;
        if (!std.mem.eql(usize, self.shape, other.shape)) return error.ShapeMismatch;
        var result = try Tensor.init(self.allocator, self.shape, self.dtype);
        var i: usize = 0;
        while (i < result.data.len) : (i += 1) {
            result.data[i] = self.data[self.indexOfFlat(i)] + other.data[other.indexOfFlat(i)];
        }
        return result;
    }

    pub fn mul(self: Tensor, scalar: f64) !Tensor {
        var result = try Tensor.init(self.allocator, self.shape, self.dtype);
        var i: usize = 0;
        while (i < result.data.len) : (i += 1) {
            result.data[i] = self.data[self.indexOfFlat(i)] * scalar;
        }
        return result;
    }

    pub fn slice(self: Tensor, start: usize, end: usize, dim: usize) !Tensor {
        if (dim >= self.shape.len) return error.InvalidDim;
        if (start >= end or end > self.shape[dim]) return error.InvalidSlice;
        const shape_copy = try self.allocator.dupe(usize, self.shape);
        shape_copy[dim] = end - start;
        const strides_copy = try self.allocator.dupe(usize, self.strides);
        return Tensor{
            .allocator = self.allocator,
            .data = self.data,
            .shape = shape_copy,
            .strides = strides_copy,
            .dtype = self.dtype,
            .offset = self.offset + start * self.strides[dim],
            .is_view = true,
        };
    }

    pub fn broadcastTo(self: *Tensor, target_shape: Shape) !Tensor {
        const current_shape = self.shape;
        const current_strides = self.strides;
        var new_strides = try self.allocator.alloc(usize, target_shape.len);
        var broadcasted = false;
        var target_idx: usize = target_shape.len;
        var current_idx: usize = current_shape.len;
        var new_idx: usize = target_shape.len;
        while (new_idx > 0) {
            new_idx -= 1;
            target_idx -= 1;
            const t_dim = target_shape[target_idx];
            if (current_idx > 0) {
                current_idx -= 1;
                const c_dim = current_shape[current_idx];
                if (c_dim == t_dim) {
                    new_strides[new_idx] = current_strides[current_idx];
                } else if (c_dim == 1) {
                    new_strides[new_idx] = 0;
                    broadcasted = true;
                } else {
                    return error.BroadcastMismatch;
                }
            } else {
                new_strides[new_idx] = 0;
                broadcasted = true;
            }
        }
        const shape_copy = try self.allocator.dupe(usize, target_shape);
        return Tensor{
            .allocator = self.allocator,
            .data = self.data,
            .shape = shape_copy,
            .strides = new_strides,
            .dtype = self.dtype,
            .offset = self.offset,
            .is_view = broadcasted,
        };
    }

    pub fn reduceSum(self: Tensor, dim: ?usize, keepdims: bool) !Tensor {
        if (self.dtype != .f64) return error.InvalidDType;
        const reduce_dim = dim orelse (if (self.shape.len == 0) 0 else self.shape.len - 1);
        if (self.shape.len == 0 or reduce_dim >= self.shape.len) return error.InvalidDim;
        var new_shape_list = ArrayList(usize).init(self.allocator);
        defer new_shape_list.deinit();
        var i: usize = 0;
        while (i < self.shape.len) : (i += 1) {
            if (i == reduce_dim) {
                if (keepdims) try new_shape_list.append(1);
            } else {
                try new_shape_list.append(self.shape[i]);
            }
        }
        const new_shape = try self.allocator.dupe(usize, new_shape_list.items);
        var result = try Tensor.init(self.allocator, new_shape, self.dtype);
        var outer_size: usize = 1;
        var d: usize = 0;
        while (d < self.shape.len) : (d += 1) {
            if (d != reduce_dim) outer_size *= self.shape[d];
        }
        const inner_size = self.shape[reduce_dim];
        var outer_idx: usize = 0;
        while (outer_idx < outer_size) : (outer_idx += 1) {
            var sum: f64 = 0.0;
            var inner_idx: usize = 0;
            while (inner_idx < inner_size) : (inner_idx += 1) {
                const flat_idx = self._flatIndex(outer_idx, inner_idx, reduce_dim);
                sum += self.get(flat_idx);
            }
            result.data[outer_idx] = sum;
        }
        return result;
    }

    fn _flatIndex(self: *const Tensor, outer: usize, inner: usize, dim: usize) usize {
        var idx_elems: usize = 0;
        var remaining = outer;
        var d: usize = 0;
        while (d < self.shape.len) : (d += 1) {
            if (d == dim) {
                idx_elems += inner * self.strides[d];
            } else {
                const stride_next = if (d + 1 < self.shape.len) self.strides[d + 1] else 1;
                const coord = (remaining / stride_next) % self.shape[d];
                idx_elems += coord * self.strides[d];
            }
        }
        return self.offset + idx_elems;
    }

    pub fn argmax(self: *const Tensor, dim: usize) !Tensor {
        if (self.dtype != .f64) return error.InvalidDType;
        if (dim >= self.shape.len) return error.InvalidDim;
        var new_shape_list = ArrayList(usize).init(self.allocator);
        defer new_shape_list.deinit();
        var i: usize = 0;
        while (i < self.shape.len) : (i += 1) {
            if (i == dim) {
                try new_shape_list.append(1);
            } else {
                try new_shape_list.append(self.shape[i]);
            }
        }
        const new_shape = try self.allocator.dupe(usize, new_shape_list.items);
        var result = try Tensor.init(self.allocator, new_shape, .f64);
        var outer_size: usize = 1;
        var d: usize = 0;
        while (d < self.shape.len) : (d += 1) {
            if (d != dim) outer_size *= self.shape[d];
        }
        const inner_size = self.shape[dim];
        var outer_idx: usize = 0;
        while (outer_idx < outer_size) : (outer_idx += 1) {
            var max_val: f64 = -std.math.inf(f64);
            var max_idx: usize = 0;
            var inner_idx: usize = 0;
            while (inner_idx < inner_size) : (inner_idx += 1) {
                const flat_idx = self._flatIndex(outer_idx, inner_idx, dim);
                const val = self.get(flat_idx);
                if (val > max_val) {
                    max_val = val;
                    max_idx = inner_idx;
                }
            }
            result.data[outer_idx] = @as(f64, @floatFromInt(max_idx));
        }
        return result;
    }

    pub fn clone(self: *const Tensor) !Tensor {
        var cl = try Tensor.init(self.allocator, self.shape, self.dtype);
        std.mem.copyForwards(f64, cl.data, self.data);
        return cl;
    }

    pub fn toComplex(self: *const Tensor) !Tensor {
        if (self.dtype != .f64) return error.InvalidDType;
        const n = totalElements(self.shape);
        var out = try Tensor.init(self.allocator, self.shape, .c64);
        var i: usize = 0;
        while (i < n) : (i += 1) {
            const v = self.get(i);
            const base = out.offset + i * 2;
            out.data[base] = v;
            out.data[base + 1] = 0.0;
        }
        return out;
    }

    pub fn save(self: *const Tensor, path: []const u8) !void {
        const file = try std.fs.cwd().createFile(path, .{});
        defer file.close();
        const writer = file.writer();
        try writer.print("{d}\n", .{self.shape.len});
        var si: usize = 0;
        while (si < self.shape.len) : (si += 1) {
            try writer.print("{d}{s}", .{ self.shape[si], if (si + 1 == self.shape.len) "\n" else " " });
        }
        try writer.print("{s}\n", .{dtypeToString(self.dtype)});
        const total = totalElements(self.shape) * (if (self.dtype == .c64) 2 else 1);
        var i: usize = 0;
        while (i < total) : (i += 1) {
            try writer.print("{d:.17}{s}", .{ self.data[self.offset + i], if (i + 1 == total) "\n" else " " });
        }
    }

    pub fn load(allocator: Allocator, path: []const u8) !Tensor {
        const file = try std.fs.cwd().openFile(path, .{});
        defer file.close();
        const content = try file.readToEndAlloc(allocator, 1024 * 1024);
        defer allocator.free(content);
        var tok = mem.tokenizeAny(u8, content, " \n\r\t");
        const shape_len_str = tok.next() orelse return error.InvalidFile;
        const shape_len = try std.fmt.parseInt(usize, shape_len_str, 10);
        var shape_buf = try allocator.alloc(usize, shape_len);
        var i: usize = 0;
        while (i < shape_len) : (i += 1) {
            const dim_str = tok.next() orelse return error.InvalidFile;
            shape_buf[i] = try std.fmt.parseInt(usize, dim_str, 10);
        }
        const dtype_str = tok.next() orelse return error.InvalidFile;
        const dtype = try parseDType(dtype_str);
        var result = try Tensor.init(allocator, shape_buf, dtype);
        allocator.free(shape_buf);
        const total_vals = totalElements(result.shape) * (if (result.dtype == .c64) 2 else 1);
        var j: usize = 0;
        while (j < total_vals) : (j += 1) {
            const val_str = tok.next() orelse return error.InvalidFile;
            result.data[result.offset + j] = try std.fmt.parseFloat(f64, val_str);
        }
        return result;
    }

    fn indexOfFlat(self: *const Tensor, flat: usize) usize {
        var pos = self.offset;
        var remaining = flat;
        var d = self.shape.len;
        while (d > 0) : (d -= 1) {
            const dim = d - 1;
            const coord = remaining % self.shape[dim];
            pos += coord * self.strides[dim];
            remaining /= self.shape[dim];
        }
        return pos;
    }

    pub fn get(self: *const Tensor, flat: usize) f64 {
        if (self.dtype != .f64) @panic("Invalid dtype for get");
        const pos = self.indexOfFlat(flat);
        return self.data[pos];
    }

    pub fn set(self: *Tensor, flat: usize, val: f64) void {
        if (self.dtype != .f64) @panic("Invalid dtype for set");
        const pos = self.indexOfFlat(flat);
        self.data[pos] = val;
    }
};

fn dtypeToString(dt: DType) []const u8 {
    return switch (dt) {
        .f64 => "f64",
        .f32 => "f32",
        .i64 => "i64",
        .i32 => "i32",
        .c64 => "c64",
    };
}

fn parseDType(s: []const u8) !DType {
    if (mem.eql(u8, s, "f64")) return .f64;
    if (mem.eql(u8, s, "f32")) return .f32;
    if (mem.eql(u8, s, "i64")) return .i64;
    if (mem.eql(u8, s, "i32")) return .i32;
    if (mem.eql(u8, s, "c64")) return .c64;
    return error.InvalidDType;
}

fn isPowerOfTwo(n: usize) bool {
    return n != 0 and (n & (n - 1)) == 0;
}

fn bitReverse(x: usize, bits: u32) usize {
    var r: usize = 0;
    var i: u32 = 0;
    while (i < bits) : (i += 1) {
        r = (r << 1) | ((x >> @intCast(usize, i)) & 1);
    }
    return r;
}

