    std.mem.copyForwards(f64, tensor.data, init_vals[0..]);
    const gamma = [_]f64{ 1.0, 1.0, 1.0, 1.0 };
    const beta = [_]f64{ 0.0, 0.0, 0.0, 0.0 };
